#include "AutomationTools.h"
#include "ControlEdits.h"
static void testAutomationTools(const File& parent,Assets& assets){
    auto root=parent.getChildFile("automation-shapes-"+Uuid().toString());root.createDirectory();
    for(int shape=0;shape<4;++shape)for(double tension:{-1.,-.3,0.,.4,1.}){double previous=-1;bool bounded=true;for(int i=0;i<=200;++i){double value=automationShape(i/200.,(AutomationCurve)shape,tension);bounded&=std::isfinite(value)&&value>=previous&&value>=0&&value<=1;previous=value;}expect(bounded&&automationShape(0,(AutomationCurve)shape,tension)==0&&automationShape(1,(AutomationCurve)shape,tension)==1,"every shaped segment remains monotonic bounded and exact at both endpoints");}
    expect(automationShape(.25,AutomationCurve::smooth)==.15625&&automationShape(.25,AutomationCurve::easeIn)==.0625&&automationShape(.25,AutomationCurve::easeOut)==.4375,"curve reference values match explicit smooth and quadratic equations");
    expect(automationShape(.5,AutomationCurve::linear,1)==1./65536&&std::abs(automationShape(.5,AutomationCurve::linear,-1)-std::pow(.5,1./16))<1e-12,"positive and negative tension warp time without changing endpoints");
    std::vector<AutomationPoint> pair{{0,.2f,false,AutomationCurve::easeIn,0},{4,.8f,false}};
    expect(std::abs(automationValue(pair.data(),2,2)-.35f)<1e-7&&automationValue(pair.data(),2,0)==.2f&&automationValue(pair.data(),2,4)==.8f,"automation evaluator uses outgoing segment shape and preserves exact boundary values");
    pair[0].hold=true;expect(automationValue(pair.data(),2,3.999)==.2f&&automationValue(pair.data(),2,4)==.8f,"Hold takes priority over stored curve metadata until the next point");pair[0].hold=false;
    AutomationGenerator settings;std::vector<AutomationPoint> points;expect(generateAutomation(4,settings,points).wasOk()&&points.size()==17&&points.front().value==0&&points[4].value==.5f&&points[8].value==1&&points.back().value==0,"sine generator produces one editable sampled cycle with exact endpoints and quarter-cycle levels");
    settings.wave=AutomationWave::triangle;expect(generateAutomation(4,settings,points).wasOk()&&points.size()==3&&points[1].beat==2&&points[1].value==1&&std::abs(automationValue(points.data(),3,1)-.5f)<1e-7,"triangle uses exact linear corners rather than unnecessary sampled points");
    settings.phase=.25;expect(generateAutomation(4,settings,points).wasOk()&&points.size()==4&&points.front().value==.5f&&points[1].beat==1&&points[1].value==1,"phase shifts generator knots and interpolates the initial partial segment");
    settings.phase=1;auto phaseOne=points;generateAutomation(4,settings,points);settings.phase=0;generateAutomation(4,settings,phaseOne);expect(points==phaseOne,"phase one aliases phase zero exactly");
    settings.wave=AutomationWave::square;expect(generateAutomation(8,settings,points).wasOk()&&points.size()==5&&points[0].hold&&automationValue(points.data(),5,1.99)==0&&automationValue(points.data(),5,2)==1,"square generator switches on exact half-period boundaries with Hold segments");
    settings.wave=AutomationWave::steps;settings.steps={0,.2f,.7f,1};expect(generateAutomation(8,settings,points).wasOk()&&points.size()==9&&points[2].value==.7f&&points[4].value==0&&points[0].hold,"step sequence repeats the explicit locally entered values");
    for(auto wave:{AutomationWave::randomHold,AutomationWave::randomSmooth}){settings.wave=wave;settings.low=.2;settings.high=.7;settings.seed=0;std::vector<AutomationPoint> again,other;expect(generateAutomation(8,settings,points).wasOk()&&generateAutomation(8,settings,again).wasOk()&&points==again,"seeded random generation reproduces identical saved points for seed zero");settings.seed=4294967295u;generateAutomation(8,settings,other);bool valid=points!=other;for(const auto& point:other)valid&=point.value>=.2f&&point.value<=.7f;expect(valid,"full unsigned seed range changes the curve without leaving normalized bounds");expect(wave==AutomationWave::randomHold?points[0].hold:points[0].curve==AutomationCurve::smooth,"random hold and smooth variants encode their actual outgoing segment behavior");}
    settings.low=settings.high=.4;expect(generateAutomation(4,settings,points).wasOk()&&std::all_of(points.begin(),points.end(),[](const auto& p){return p.value==.4f;}),"equal generator bounds create a constant curve");
    auto retained=points;for(int bad=0;bad<11;++bad){settings={};double length=4;if(bad==0)settings.period=.01;if(bad==1)settings.period=.0625;if(bad==2)settings.phase=std::nan("");if(bad==3)settings.low=.9,settings.high=.2;if(bad==4)settings.resolution=5;if(bad==5)settings.steps.clear();if(bad==6)settings.steps[0]=std::nanf("");if(bad==7)settings.wave=(AutomationWave)99;if(bad==8)length=601;if(bad==9)settings.high=std::numeric_limits<double>::infinity();if(bad==10)settings.steps.resize(33);expect(generateAutomation(length,settings,points).failed()&&points==retained,"invalid or oversized generation retains the previous draft atomically");}
    auto source=emptyProject();source.bpm=120;source.swing=0;source.songMode=true;source.loop=false;source.tracks[7].send=0;source.patterns[0].length=4;source.patterns[0].lanes[7]={{0,4,60,.8f}};source.clips.push_back({7,0,0,4});Clip automation;automation.track=7;automation.automationTrack=7;automation.automationTarget=0;automation.length=4;automation.points=pair;source.clips.push_back(automation);
    auto file=root.getChildFile("shaped-automation.pulse");Project read;expect(saveProject(source,file).wasOk()&&loadProject(file,read).wasOk()&&read.clips[1].points==pair,"schema eighteen preserves complete automation segment settings in a checked save");
    auto json=projectToJson(source);json.getDynamicObject()->setProperty("schema",17);expect(projectFromJson(json,read).failed()&&read.clips[1].points==pair,"curved automation cannot be mislabeled as schema seventeen");
    auto linear=source;linear.masterSoftClip=true;linear.clips[1].points[0].curve=AutomationCurve::linear;linear.clips[1].points[0].tension=0;json=projectToJson(linear);json.getDynamicObject()->setProperty("schema",17);for(auto& p:*(*json["clips"].getArray())[1]["points"].getArray()){p.getDynamicObject()->removeProperty("curve");p.getDynamicObject()->removeProperty("tension");}expect(projectFromJson(json,read).wasOk()&&read.clips[1].points==linear.clips[1].points,"old projects migrate missing segment metadata to neutral linear defaults");
    auto oldAudio=render(linear,assets,root,16000,127),migrated=render(read,assets,root,16000,733);bool equal=true;for(int c=0;c<2;++c)for(int i=0;i<16000;++i)equal&=oldAudio.getSample(c,i)==migrated.getSample(c,i);expect(equal,"legacy linear automation remains sample-exact after schema migration");
    for(int bad=0;bad<7;++bad){json=projectToJson(source);auto* point=(*(*json["clips"].getArray())[1]["points"].getArray())[0].getDynamicObject();if(bad==0)point->removeProperty("curve");if(bad==1)point->setProperty("curve",true);if(bad==2)point->setProperty("curve",4);if(bad==3)point->setProperty("tension",1.00001);if(bad==4)point->setProperty("tension","0");if(bad==5)point->removeProperty("tension");if(bad==6)point->setProperty("hold",1);auto before=JSON::toString(projectToJson(read));expect(projectFromJson(json,read).failed()&&JSON::toString(projectToJson(read))==before,"invalid modern curve fields reject without replacing the loaded song");}
    settings={};settings.low=.1;settings.high=.9;settings.period=2;generateAutomation(4,settings,points);auto next=source;expect(replaceAutomationPoints(next,1,points).wasOk()&&next.clips[1].beat==source.clips[1].beat&&next.clips[1].automationTrack==7&&next.patterns[0].lanes[7]==source.patterns[0].lanes[7],"generator replacement preserves clip location target and source notes");auto unchanged=JSON::toString(projectToJson(next));auto invalidPoints=points;invalidPoints[0].tension=std::nanf("");expect(replaceAutomationPoints(next,1,invalidPoints).failed()&&JSON::toString(projectToJson(next))==unchanged,"invalid replacement retains the complete song");
    auto a=render(next,assets,root,48000,127),b=render(next,assets,root,48000,733);equal=true;double difference=0;auto flat=render(linear,assets,root,48000);for(int c=0;c<2;++c)for(int i=0;i<48000;++i){equal&=a.getSample(c,i)==b.getSample(c,i);difference+=std::abs(a.getSample(c,i)-flat.getSample(c,i));}expect(equal&&difference>1&&a.getMagnitude(0,0,48000)>.001,"generated automation changes audible playback and stays exact across callback sizes");
    RenderSettings options;options.bits=32;options.tailSeconds=0;auto wav=root.getChildFile("automation.wav");auto result=renderAudio(next,assets,root,wav,options);AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(wav));AudioBuffer<float> decoded(2,48000);equal=result.wasOk()&&reader;if(equal){reader->read(&decoded,0,48000,0,true,true);for(int c=0;c<2;++c)for(int i=0;i<48000;++i)equal&=decoded.getSample(c,i)==a.getSample(c,i);}expect(equal,"generated float WAV export matches real-time callback samples exactly");
    auto dense=source;dense.clips.clear();for(int c=0;c<17;++c){auto row=automation;row.points.clear();for(int n=0;n<240;++n)row.points.push_back({4.*n/239,.5f,false});dense.clips.push_back(row);}dense.clips.push_back(automation);auto denseBefore=JSON::toString(projectToJson(dense));std::vector<AutomationPoint> capacity;settings={};settings.period=4./254;settings.resolution=4; // Deliberately exceeds a single clip before project mutation.
    auto many=automation.points;many.clear();for(int n=0;n<256;++n)many.push_back({4.*n/255,.5f,false});expect(replaceAutomationPoints(dense,17,many).failed()&&JSON::toString(projectToJson(dense))==denseBefore,"a valid individual curve cannot exceed the whole-project point budget");
    Project controlled;auto ops=JSON::parse(R"([{"op":"generate_automation","clip":1,"wave":"random_smooth","period":2,"resolution":8,"seed":4294967295,"low":0.2,"high":0.7}])");expect(applyControlEdits(source,ops,controlled).wasOk()&&controlled.clips[1].points.size()==17&&controlled.clips[1].points[0].curve==AutomationCurve::smooth,"existing MCP edit transaction generates a seeded shaped curve in place");
    auto set=JSON::parse(R"([{"op":"set_automation_points","clip":1,"points":[{"beat":0,"value":0.2,"curve":3,"tension":-0.4},{"beat":4,"value":0.9}]}])");expect(applyControlEdits(source,set,controlled).wasOk()&&controlled.clips[1].points[0].curve==AutomationCurve::easeOut&&controlled.clips[1].points[0].tension==-.4f,"MCP replaces existing points with complete segment shapes and tension");
    for(auto bad:{R"([{"op":"set_song","title":"Must roll back"},{"op":"generate_automation","clip":1,"wave":"sine","period":0.0625}])",R"([{"op":"generate_automation","clip":0,"wave":"sine","period":4}])",R"([{"op":"generate_automation","clip":1,"wave":"sine","period":4,"seed":true}])",R"([{"op":"set_automation_points","clip":1,"points":[{"beat":0,"value":0,"curve":true},{"beat":4,"value":1}]}])"}){auto before=JSON::toString(projectToJson(controlled));expect(applyControlEdits(source,JSON::parse(bad),controlled).failed()&&JSON::toString(projectToJson(controlled))==before,"invalid generator or point batches preserve all earlier project state");}
}
